package dev.pedro.learning.ecommerce.inventory.outbox;
import com.fasterxml.jackson.databind.ObjectMapper; import dev.pedro.learning.ecommerce.inventory.event.EventEnvelope; import jakarta.enterprise.context.ApplicationScoped;
@ApplicationScoped public class OutboxWriter { private final OutboxEventRepository repo; private final ObjectMapper mapper; public OutboxWriter(OutboxEventRepository repo,ObjectMapper mapper){this.repo=repo;this.mapper=mapper;} public void append(String topic,String aggregateId,EventEnvelope<?> envelope){OutboxEvent e=new OutboxEvent();e.id=envelope.eventId();e.aggregateType=topic;e.aggregateId=aggregateId;e.type=envelope.eventType();e.payload=mapper.valueToTree(envelope);e.occurredAt=envelope.occurredAt();repo.persist(e);} }
